import type { UseFormReturnType } from '@mantine/form';

export type FieldType =
  | 'text'
  | 'richText'
  | 'boolean'
  | 'json'
  | 'select'
  | 'image'
  | 'file'
  | 'reference';

export interface SelectOption {
  id: string;
  value: string;
  label: string;
}

// One shape for every field type: options of other types are kept but left out of the payload
export interface FieldValues {
  id: string;
  type: FieldType;
  label: string;
  key: string;
  description: string;
  required: boolean;
  textDisplay: 'input' | 'textarea';
  maxLength: number | string;
  textDefault: string;
  booleanDefault: 'true' | 'false';
  jsonDefault: string;
  options: SelectOption[];
  defaultOption: string | null;
  targetModel: string | null;
  allowMultiple: boolean;
}

export type FieldFormType = UseFormReturnType<FieldValues>;

export interface ContentModelValues {
  name: string;
  key: string;
  description: string;
  fields: FieldValues[];
}

interface BaseFieldPayload {
  label: string;
  key: string;
  description: string;
  required: boolean;
}

export type FieldPayload = BaseFieldPayload &
  (
    | {
        type: 'text';
        display: 'input' | 'textarea';
        maxLength: number | null;
        defaultValue: string;
      }
    | { type: 'boolean'; defaultValue: boolean }
    | { type: 'json'; defaultValue: unknown }
    | {
        type: 'select';
        options: { value: string; label: string }[];
        defaultValue: string | null;
      }
    | { type: 'reference'; targetModel: string; allowMultiple: boolean }
    | { type: 'richText' | 'image' | 'file' }
  );

export interface ContentModelPayload {
  name: string;
  key: string;
  description: string;
  fields: FieldPayload[];
}

export type ContentModelFormType = UseFormReturnType<ContentModelValues, ContentModelPayload>;

import { randomId } from '@mantine/hooks';
import type {
  ContentModelPayload,
  ContentModelValues,
  FieldPayload,
  FieldType,
  FieldValues,
  SelectOption,
} from './types';

export const KEY_PATTERN = /^[a-z0-9_]+$/;

export function slugify(value: string) {
  return value
    .normalize('NFKD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');
}

export function createOption(): SelectOption {
  return { id: randomId(), value: '', label: '' };
}

export function createField(type: FieldType): FieldValues {
  return {
    id: randomId(),
    type,
    label: '',
    key: '',
    description: '',
    required: false,
    textDisplay: 'input',
    maxLength: '',
    textDefault: '',
    booleanDefault: 'false',
    jsonDefault: '',
    options: [createOption(), createOption()],
    defaultOption: null,
    targetModel: null,
    allowMultiple: false,
  };
}

function toFieldPayload(field: FieldValues): FieldPayload {
  const base = {
    label: field.label.trim(),
    key: field.key,
    description: field.description.trim(),
    required: field.required,
  };

  switch (field.type) {
    case 'text':
      return {
        ...base,
        type: 'text',
        display: field.textDisplay,
        maxLength: field.maxLength === '' ? null : Number(field.maxLength),
        defaultValue: field.textDefault,
      };
    case 'boolean':
      return { ...base, type: 'boolean', defaultValue: field.booleanDefault === 'true' };
    case 'json':
      return {
        ...base,
        type: 'json',
        defaultValue: field.jsonDefault.trim() === '' ? null : JSON.parse(field.jsonDefault),
      };
    case 'select':
      return {
        ...base,
        type: 'select',
        options: field.options.map(({ value, label }) => ({ value, label })),
        defaultValue: field.defaultOption,
      };
    case 'reference':
      return {
        ...base,
        type: 'reference',
        targetModel: field.targetModel!,
        allowMultiple: field.allowMultiple,
      };
    default:
      return { ...base, type: field.type };
  }
}

export function toModelPayload(values: ContentModelValues): ContentModelPayload {
  return {
    name: values.name.trim(),
    key: values.key,
    description: values.description.trim(),
    fields: values.fields.map(toFieldPayload),
  };
}
